-- Current independent-contractor agreement.
-- Inserts ic-agreement-2026-10-05 once. The body is base64 so the statement
-- has no dollar quotes and cannot double the HTML the way the retired seed did.
-- Does not update the previously repaired agreement row.

insert into public.driver_agreement_versions (version, title, body_html, sha256)
select
  'ic-agreement-2026-10-05',
  'Clemson RIDES Independent Contractor Agreement',
  payload.body,
  encode(extensions.digest(convert_to(payload.body, 'UTF8'), 'sha256'), 'hex')
from (
  select convert_from(decode(
    '',
    'base64'
  ), 'UTF8') as body
) payload
on conflict (version) do nothing;
